#!/usr/bin/env node
// LALINEA_HALLOWEEN — aggiornamento locale reversibile; non esegue Git o richieste di rete.
import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

const COMPONENT="\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { createPortal } from \"react-dom\";\n\n// LALINEA_HALLOWEEN — cambia true in false per spegnere tutte le decorazioni.\nconst LALINEA_HALLOWEEN_ENABLED = true;\nconst START_AT = Date.parse(\"2026-10-26T00:00:00+01:00\");\nconst END_AT = Date.parse(\"2026-11-02T00:00:00+01:00\");\nconst ATLAS_URL = \"/lalinea-halloween-2026/adesivi.png?v=e70e6b44fa39\";\nconst ATLAS_WIDTH = 1254;\nconst ATLAS_HEIGHT = 1254;\nconst STICKERS: {name:string;x:number;y:number;w:number;h:number}[] = [{\"name\":\"zucca\",\"x\":12,\"y\":39,\"w\":300,\"h\":289},{\"name\":\"gatto\",\"x\":349,\"y\":40,\"w\":262,\"h\":289},{\"name\":\"fantasma\",\"x\":641,\"y\":42,\"w\":272,\"h\":284},{\"name\":\"castello\",\"x\":976,\"y\":13,\"w\":270,\"h\":316},{\"name\":\"calderone\",\"x\":25,\"y\":333,\"w\":269,\"h\":283},{\"name\":\"mummia\",\"x\":353,\"y\":347,\"w\":243,\"h\":272},{\"name\":\"pirata\",\"x\":632,\"y\":348,\"w\":305,\"h\":273},{\"name\":\"pipistrelli\",\"x\":962,\"y\":366,\"w\":281,\"h\":245},{\"name\":\"frankenstein\",\"x\":34,\"y\":633,\"w\":259,\"h\":278},{\"name\":\"zombie\",\"x\":334,\"y\":620,\"w\":291,\"h\":314},{\"name\":\"scheletro\",\"x\":656,\"y\":633,\"w\":264,\"h\":303},{\"name\":\"caramelle\",\"x\":972,\"y\":634,\"w\":259,\"h\":282},{\"name\":\"ragnatela\",\"x\":21,\"y\":925,\"w\":291,\"h\":299},{\"name\":\"sfera\",\"x\":367,\"y\":945,\"w\":234,\"h\":278},{\"name\":\"cappello\",\"x\":642,\"y\":951,\"w\":305,\"h\":265},{\"name\":\"cestino\",\"x\":980,\"y\":930,\"w\":273,\"h\":288}];\nconst ORDER = [9, 0, 2, 8, 4, 7, 10, 1, 13, 11, 5, 15, 3, 12, 14, 6];\nconst CSS = \"/* LALINEA_HALLOWEEN — stili limitati esclusivamente agli adesivi. */\\n#ll-hw26-root{position:fixed!important;inset:0!important;z-index:40!important;overflow:hidden!important;pointer-events:none!important;user-select:none!important;isolation:isolate;contain:layout style;}\\n#ll-hw26-root,#ll-hw26-root *{box-sizing:border-box!important;pointer-events:none!important;}\\n#ll-hw26-root .ll-hw26-item{position:absolute;display:flex;align-items:center;justify-content:center;margin:0;padding:0;filter:drop-shadow(0 2px 3px #0007);}\\n#ll-hw26-root .ll-hw26-sprite{display:block;flex:none;background-repeat:no-repeat;}\\n@media print{#ll-hw26-root{display:none!important;}}\\n\";\nconst EXCLUDE = 'header,nav,footer,form,button,a,dialog,[role=\"dialog\"],[aria-modal=\"true\"],[inert],[aria-hidden=\"true\"],#ll-carrello,[data-halloween-exclude]';\ntype Box = {left:number;top:number;right:number;bottom:number};\ntype Decoration = {key:string;x:number;y:number;size:number;sticker:number};\nconst intersects = (a:Box,b:Box,gap=3) => a.left < b.right+gap && a.right+gap > b.left && a.top < b.bottom+gap && a.bottom+gap > b.top;\n\nexport default function LaLineaHalloween2026() {\n  const [active,setActive] = useState(false);\n  const [decorations,setDecorations] = useState<Decoration[]>([]);\n\n  useEffect(() => {\n    if (!LALINEA_HALLOWEEN_ENABLED) return;\n    let timer:ReturnType<typeof setTimeout>|undefined;\n    const sync = () => {\n      if (timer !== undefined) clearTimeout(timer);\n      const now = Date.now();\n      setActive(now >= START_AT && now < END_AT);\n      const next = now < START_AT ? START_AT : END_AT;\n      if (next > now) timer = setTimeout(sync,Math.min(next-now,2147483647));\n    };\n    sync();\n    document.addEventListener(\"visibilitychange\",sync);\n    window.addEventListener(\"pageshow\",sync);\n    return () => {\n      if (timer !== undefined) clearTimeout(timer);\n      document.removeEventListener(\"visibilitychange\",sync);\n      window.removeEventListener(\"pageshow\",sync);\n    };\n  },[]);\n\n  useEffect(() => {\n    if (!active || !LALINEA_HALLOWEEN_ENABLED) return;\n    let pending=0;\n    let stopped=false;\n    const root=document.getElementById(\"ll-hw26-root\");\n    const visible=(r:DOMRect) => r.width>0 && r.height>0 && r.bottom>0 && r.top<window.innerHeight && r.right>0 && r.left<window.innerWidth;\n    const measure=() => {\n      pending=0;\n      if (stopped) return;\n      const compact=window.innerWidth<=640;\n      const size=compact?36:48;\n      const limit=compact?16:24;\n      const obstacles:Box[]=[];\n      // Lettura del contenuto: i disegni occupano solo spazi liberi.\n      const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);\n      let node:Node|null;\n      while ((node=walker.nextNode())) {\n        if (!node.textContent?.trim()) continue;\n        const parent=node.parentElement;\n        if (!parent || root?.contains(parent) || parent.closest('script,style,noscript,[hidden],[inert]')) continue;\n        const range=document.createRange();\n        range.selectNodeContents(node);\n        for (const r of Array.from(range.getClientRects())) if (visible(r)) obstacles.push(r);\n      }\n      document.querySelectorAll<HTMLElement>('button,a,input,select,textarea,video,img,iframe,canvas,header,nav,footer,form,dialog,[role=\"button\"],[role=\"dialog\"],[data-halloween-protect]').forEach(element => {\n        if (root?.contains(element)) return;\n        const r=element.getBoundingClientRect();\n        if (visible(r)) obstacles.push(r);\n      });\n      const result:Decoration[]=[];\n      const perContainer=new Map<Element,number>();\n      const headings=document.querySelectorAll<HTMLElement>('h1,h2,h3,h4,[role=\"heading\"],p[class*=\"tracking-\"]');\n      headings.forEach((heading,index) => {\n        if (result.length>=limit || heading.closest(EXCLUDE)) return;\n        if (/carrell|checkout|accedi|login|password|pagament|riepilog|totale|conferma ordine/i.test(heading.textContent||\"\")) return;\n        const box=heading.getBoundingClientRect();\n        if (!visible(box) || getComputedStyle(heading).visibility!==\"visible\") return;\n        const range=document.createRange();\n        range.selectNodeContents(heading);\n        const text=range.getBoundingClientRect();\n        if (!visible(text)) return;\n        const container=heading.closest('article,section,[data-halloween-section],div[class*=\"rounded-3xl\"],div[class*=\"rounded-2xl\"]')||heading.parentElement;\n        if (!container || container.closest(EXCLUDE)) return;\n        const count=perContainer.get(container)||0;\n        if (count >= (compact?6:8)) return;\n        const card=container.getBoundingClientRect();\n        const left=Math.max(card.left+8,12);\n        const right=Math.min(card.right-8,window.innerWidth-12);\n        const candidates:[number,number][]=[];\n        // Piccoli gruppi vicini al titolo, poi gli angoli liberi del riquadro.\n        for (let i=0;i<3;i++) candidates.push([text.right+10+i*(size+7),text.top+(Math.min(text.height,size)-size)/2]);\n        candidates.push([right-size,card.top+8],[right-size*2-7,card.top+8]);\n        candidates.push([right-size,box.bottom+8],[left,box.top-size-8]);\n        candidates.push([right-size,box.top+size+14],[right-size,box.top+size*2+24]);\n        candidates.push([right-size,card.bottom-size-8],[left,card.bottom-size-8]);\n        let placed=0;\n        for (const [rawX,rawY] of candidates) {\n          if (placed >= (compact?3:4) || count+placed >= (compact?6:8) || result.length>=limit) break;\n          const x=Math.round(rawX), y=Math.round(rawY);\n          const area={left:x,top:y,right:x+size,bottom:y+size};\n          if (x<left || x+size>right || y<Math.max(card.top+3,4) || y+size>Math.min(card.bottom-3,window.innerHeight-4)) continue;\n          if (obstacles.some(r=>intersects(area,r))) continue;\n          if (result.some(d=>intersects(area,{left:d.x,top:d.y,right:d.x+d.size,bottom:d.y+d.size},7))) continue;\n          const hit=document.elementFromPoint(x+size/2,y+size/2);\n          if (hit?.closest(EXCLUDE)) continue;\n          result.push({key:`${index}-${placed}`,x,y,size,sticker:ORDER[result.length%ORDER.length]});\n          placed++;\n        }\n        perContainer.set(container,count+placed);\n      });\n      setDecorations(previous=>JSON.stringify(previous)===JSON.stringify(result)?previous:result);\n    };\n    const schedule=() => {\n      if (!stopped && !pending) pending=requestAnimationFrame(measure);\n    };\n    const observer=new MutationObserver(records=>{\n      const outside=records.some(record=>{\n        if (root && (record.target===root || root.contains(record.target))) return false;\n        if (record.type===\"childList\") {\n          const nodes=[...Array.from(record.addedNodes),...Array.from(record.removedNodes)];\n          if (nodes.length && nodes.every(n=>n===root || !!root?.contains(n))) return false;\n        }\n        return true;\n      });\n      if (outside) schedule();\n    });\n    observer.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:[\"class\",\"style\",\"hidden\",\"aria-hidden\"]});\n    const resize=typeof ResizeObserver!==\"undefined\"?new ResizeObserver(schedule):null;\n    resize?.observe(document.body);\n    schedule();\n    window.addEventListener(\"scroll\",schedule,{capture:true,passive:true});\n    window.addEventListener(\"resize\",schedule);\n    window.addEventListener(\"pageshow\",schedule);\n    document.fonts?.addEventListener(\"loadingdone\",schedule);\n    return ()=>{\n      stopped=true;\n      if (pending) cancelAnimationFrame(pending);\n      observer.disconnect();\n      resize?.disconnect();\n      window.removeEventListener(\"scroll\",schedule,true);\n      window.removeEventListener(\"resize\",schedule);\n      window.removeEventListener(\"pageshow\",schedule);\n      document.fonts?.removeEventListener(\"loadingdone\",schedule);\n    };\n  },[active]);\n\n  if (!active || !LALINEA_HALLOWEEN_ENABLED) return null;\n  return createPortal(<div id=\"ll-hw26-root\" aria-hidden=\"true\" style={{pointerEvents:\"none\"}}>\n    <style>{CSS}</style>\n    {decorations.map(d=>{\n      const art=STICKERS[d.sticker];\n      const longest=Math.max(art.w,art.h);\n      return <span key={d.key} className=\"ll-hw26-item\" data-lalinea-halloween={art.name} style={{left:d.x,top:d.y,width:d.size,height:d.size}}>\n        <span className=\"ll-hw26-sprite\" style={{width:`${art.w/longest*100}%`,height:`${art.h/longest*100}%`,backgroundImage:`url(\"${ATLAS_URL}\")`,backgroundSize:`${ATLAS_WIDTH/art.w*100}% ${ATLAS_HEIGHT/art.h*100}%`,backgroundPosition:`${art.x/(ATLAS_WIDTH-art.w)*100}% ${art.y/(ATLAS_HEIGHT-art.h)*100}%`}}/>\n      </span>;\n    })}\n  </div>,document.body);\n}\n";
const ATLAS=Buffer.from("",'base64');
const LEGACY_DIGESTS=["269f57bb300b4f9e7abbb9112246bef6bde35a2c4e32c7c37dfce61d9e3c6b7c","38439b5f3284aca51e197a69283e2781067fa90b3496dc80ebbbf83dd564d42e"];
const IMPORT='/* LALINEA_HALLOWEEN_2026_IMPORT_BEGIN */\nimport LaLineaHalloween2026 from "./components/LaLineaHalloween2026";\n/* LALINEA_HALLOWEEN_2026_IMPORT_END */\n';
const MOUNT='{/* LALINEA_HALLOWEEN_2026_MOUNT_BEGIN */}\n        <LaLineaHalloween2026 />\n        {/* LALINEA_HALLOWEEN_2026_MOUNT_END */}\n      ';
const args=process.argv.slice(2);
if (args.some(a=>a.startsWith('--')&&!['--verifica','--rimuovi'].includes(a))) {console.error('Usa --verifica oppure --rimuovi.');process.exit(1);}
const dirs=args.filter(a=>!a.startsWith('--'));
if(dirs.length>1){console.error('Indica una sola cartella del progetto.');process.exit(1);}
const project=path.resolve(dirs[0]||process.cwd());
const check=args.includes('--verifica'), remove=args.includes('--rimuovi');
const digest=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const enabled=text=>text.replace('const LALINEA_HALLOWEEN_ENABLED = false;','const LALINEA_HALLOWEEN_ENABLED = true;');
const read=async file=>{try{return await fs.readFile(file);}catch(e){if(e.code==='ENOENT')return null;throw e;}};
const same=(a,b)=>a===null?b===null:b!==null&&a.equals(b);
const atomic=async(file,bytes)=>{
  await fs.mkdir(path.dirname(file),{recursive:true});
  const temp=file+'.halloween-'+crypto.randomUUID()+'.tmp';
  try{await fs.writeFile(temp,bytes,{flag:'wx'});await fs.rename(temp,file);}
  finally{await fs.rm(temp,{force:true});}
};
const apply=async changes=>{
  const done=[];
  try{
    for(const change of changes){
      if(change.after===null)await fs.unlink(change.file);
      else await atomic(change.file,change.after);
      done.push(change);
    }
  }catch(error){
    for(const c of done.reverse()){
      try{if(c.before===null)await fs.rm(c.file,{force:true});else await atomic(c.file,c.before);}
      catch(rollbackError){console.error('Ripristino da controllare per '+c.file+': '+rollbackError.message);}
    }
    throw error;
  }
};

try{
  if(await read(path.join(project,'package.json'))===null)throw new Error('package.json non trovato: indica la cartella lalinea-shop.');
  const layouts=[];
  for(const rel of ['app/layout.tsx','src/app/layout.tsx']){
    const bytes=await read(path.join(project,rel));
    if(bytes!==null)layouts.push({rel,bytes});
  }
  if(layouts.length!==1)throw new Error('Serve un solo layout app/layout.tsx oppure src/app/layout.tsx.');
  const {rel,bytes:oldLayout}=layouts[0];
  const layoutPath=path.join(project,rel), appDir=path.dirname(layoutPath);
  const componentPath=path.join(appDir,'components','LaLineaHalloween2026.tsx');
  const assetPath=path.join(project,'public','lalinea-halloween-2026','adesivi.png');
  const oldComponent=await read(componentPath),oldAsset=await read(assetPath);
  const layout=oldLayout.toString('utf8');
  const occurrences=(s,t)=>s.split(t).length-1;
  const installed=occurrences(layout,IMPORT)===1&&occurrences(layout,MOUNT)===1;
  if(layout.includes('LALINEA_HALLOWEEN_2026_')&&!installed)throw new Error('Marcatori Halloween modificati o duplicati: conservo i file esistenti.');
  if(oldComponent!==null){
    const hash=digest(enabled(oldComponent.toString('utf8')));
    if(hash!==digest(COMPONENT)&&!LEGACY_DIGESTS.includes(hash))throw new Error('Componente Halloween modificato manualmente: conservo i file esistenti.');
  }
  if(oldAsset!==null&&digest(oldAsset)!==digest(ATLAS))throw new Error('Esiste un diverso adesivi.png: conservo il file esistente.');

  if(remove){
    if(!installed&&oldComponent!==null)throw new Error('Componente presente senza i collegamenti previsti.');
    const restored=installed?Buffer.from(layout.replace(IMPORT,'').replace(MOUNT,'')):oldLayout;
    const changes=[];
    if(!same(oldLayout,restored))changes.push({file:layoutPath,before:oldLayout,after:restored});
    if(oldComponent!==null)changes.push({file:componentPath,before:oldComponent,after:null});
    if(oldAsset!==null)changes.push({file:assetPath,before:oldAsset,after:null});
    if(check){console.log('Verifica OK: rimozione possibile; le altre modifiche vengono conservate.');process.exit(0);}
    await apply(changes);
    console.log(changes.length?'Halloween rimosso: eliminati solo il componente, gli adesivi e i due collegamenti.':'Halloween è già rimosso.');
    process.exit(0);
  }
  if(installed&&oldComponent===null)throw new Error('Collegamenti presenti ma componente mancante.');
  if(!installed&&oldComponent!==null)throw new Error('Componente esistente senza i collegamenti previsti.');
  let updated=layout;
  if(!installed){
    if(layout.includes('LaLineaHalloween2026')||occurrences(layout,'</body>')!==1||!/export\s+default\b/.test(layout))throw new Error('Layout non riconosciuto: nessuna modifica eseguita.');
    const importMatch=/^import\s/m.exec(layout);
    if(!importMatch)throw new Error('Non trovo gli import nel layout.');
    updated=layout.slice(0,importMatch.index)+IMPORT+layout.slice(importMatch.index);
    updated=updated.replace('</body>',MOUNT+'</body>');
  }
  const disabled=oldComponent?.toString('utf8').includes('const LALINEA_HALLOWEEN_ENABLED = false;');
  const component=Buffer.from(disabled?COMPONENT.replace('const LALINEA_HALLOWEEN_ENABLED = true;','const LALINEA_HALLOWEEN_ENABLED = false;'):COMPONENT);
  const changes=[];
  if(!same(oldAsset,ATLAS))changes.push({file:assetPath,before:oldAsset,after:ATLAS});
  if(!same(oldComponent,component))changes.push({file:componentPath,before:oldComponent,after:component});
  const newLayout=Buffer.from(updated);
  if(!same(oldLayout,newLayout))changes.push({file:layoutPath,before:oldLayout,after:newLayout});
  if(check){console.log('Verifica OK: '+(installed?'aggiornamento della versione esistente, senza duplicati.':'installazione possibile.')+' 16 adesivi LALINEA, zombie compresi.');process.exit(0);}
  await apply(changes);
  console.log(changes.length?'Halloween '+(installed?'aggiornato':'installato')+': 16 adesivi LALINEA, più decorazioni e zombie.':'Halloween è già aggiornato. Nessun duplicato aggiunto.');
  console.log('page.tsx, prodotti, carrello, VIP e gioco non sono stati modificati.');
  if(disabled)console.log('Interruttore disattivato conservato.');
  console.log('Decorazioni fino al 1 novembre incluso; si nascondono il 2 novembre 2026 alle 00:00 italiane.');
  console.log('Esegui npm run build nella cartella lalinea-shop, poi il normale Git.');
}catch(error){console.error('Operazione interrotta: '+error.message);process.exitCode=1;}
